use lg_cli::{Flags, Settings};
use lg_parse::Config;
use lg_core::RoundingMode;

#[test]
fn disc_l24() {
    let cfg = Config::parse("[report]\nrounding = comercial\n").unwrap();
    let s = Settings::resolve(&cfg, &Flags::default()).unwrap();
    assert_eq!(s.rounding, RoundingMode::HalfUp);
}
